import { Component, ComponentInterface, Element, Fragment, h, Host, Listen, Prop } from '@stencil/core';
import { NavigationSizes, Target } from '../../../../../../types';
import { verifyTarget } from '../../../../../../utils/link-helper';

/**
 * @slot default - here is any HTML content allowed.
 * @slot label - named slot 'label', here is any HTML content allowed.
 */
@Component({
  tag: 'groupui-global-side-navigation-item',
  styleUrl: 'global-side-navigation-item.scss',
  shadow: true,
})
export class GlobalSideNavigationItem implements ComponentInterface {
  /**
   * icon name e.g. 'clock-24'. Use the matching 24px sized icons
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/clock-24.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * set item as active
   */
  @Prop({ reflect: true }) readonly active: boolean;

  /**
   * set item as open
   */
  @Prop({ reflect: true }) readonly open: boolean;

  /**
   * disables the navigation item
   */
  @Prop({ reflect: true }) readonly disabled: boolean;

  /**
   * URL that the hyperlink points to.
   */
  @Prop({ reflect: true }) readonly href: string;

  /**
   * where to open the linked URL. On target 'none' no target attribute will be set.
   */
  @Prop({ reflect: true }) readonly target: Target = 'self';

  /**
   * @internal
   */
  @Prop({ reflect: true }) readonly size: NavigationSizes = 's';

  /**
   * @internal
   */
  @Prop({ reflect: true }) readonly divider: boolean;

  /**
   * @internal
   */
  @Prop({ reflect: true }) readonly treeLayout: boolean;

  /**
     @internal
     */
  @Prop({ reflect: true }) readonly iconOnly: boolean = false;

  /**
   * sets a custom accessible text for the icon
   */
  @Prop({ reflect: true, attribute: 'a11y-label-icon' }) readonly a11yLabelIcon: string;

  @Element() host: HTMLElement;

  @Listen('click')
  handleClick(event: Event): void {
    if (this.disabled) {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  }

  @Listen('keyup')
  handleKeyUp(event: KeyboardEvent): void {
    // "NavItems" should not trigger on space key. If item is a button instead of a link, we have to actively prevent the default action
    if (event.key === ' ') {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  }

  @Listen('focus')
  handleFocus(event: FocusEvent): void {
    if (this.disabled) {
      event.preventDefault();
      event.stopImmediatePropagation();
      this.host.blur();
    }
  }

  componentDidLoad() {
    this.host.style.setProperty('--nesting-level', this.getNestingLevel().level.toString());
    this.host.style.setProperty('--icon-count', this.getNestingLevel().icons.toString());
  }

  private getNestingLevel(): { level: number; icons: number } {
    let level = 0;
    let icons = 0;

    let parent = this.host.parentNode;
    let currentIcon = this.icon;

    if (!this.hasChildItems() && (parent as HTMLGroupuiGlobalSideNavigationItemElement).treeLayout) {
      icons++;
    }

    while (parent != null) {
      if (parent.nodeName === 'GROUPUI-GLOBAL-SIDE-NAVIGATION') {
        break;
      }
      if (parent.nodeName === 'GROUPUI-GLOBAL-SIDE-NAVIGATION-ITEM') {
        level++;
        const parentItem = parent as HTMLGroupuiGlobalSideNavigationItemElement;
        if (!!parentItem.icon && !currentIcon) {
          icons++;
        }
        currentIcon = parentItem.icon;
      }
      parent = parent.parentNode;
    }

    return { level, icons };
  }

  private accordionIcon() {
    if (this.hasChildItems()) {
      if (this.open) {
        return <groupui-icon id="arrow" name="chevron-up-24" aria-hidden="true" />;
      } else {
        return <groupui-icon id="arrow" name="chevron-down-24" aria-hidden="true" />;
      }
    }
  }

  private getChildrenIndicatorIcon() {
    if (this.iconOnly && this.hasChildItems()) {
      return <groupui-icon id="has-child" name="chevron-right-16" aria-hidden="true" />;
    }
  }

  private hasChildItems(): boolean {
    let hasItemChild = false;
    this.host.childNodes.forEach((child) => {
      if (child.nodeName === 'GROUPUI-GLOBAL-SIDE-NAVIGATION-ITEM') {
        hasItemChild = true;
      }
    });
    return hasItemChild;
  }

  private clickableElement() {
    if (this.href) {
      return (
        <a tabIndex={this.disabled ? -1 : 0} href={this.href} target={verifyTarget(this.target)}>
          {this.clickableContent()}
        </a>
      );
    } else {
      return (
        <button tabIndex={this.disabled ? -1 : 0} type="button" disabled={this.disabled}>
          {this.clickableContent()}
        </button>
      );
    }
  }

  private clickableContent() {
    return (
      <Fragment>
        {this.treeLayout && !this.iconOnly && this.accordionIcon()}
        {this.getIcon()}
        {this.getChildrenIndicatorIcon()}
        {!this.iconOnly && <slot name="label"></slot>}
        {!this.treeLayout && !this.iconOnly && this.accordionIcon()}
      </Fragment>
    );
  }

  private getIcon() {
    if (this.icon || this.iconSource) {
      return (
        <groupui-icon
          name={this.icon}
          src={this.iconSource}
          alt={this.a11yLabelIcon}
          aria-hidden={this.a11yLabelIcon ? null : 'true'}
        />
      );
    }
  }

  private iconOnlyWithoutIcon() {
    return this.iconOnly && !this.icon && !this.iconSource;
  }

  render() {
    if (this.iconOnlyWithoutIcon()) return;

    return (
      <Host>
        <div>
          {this.clickableElement()}
          {!this.iconOnly && this.open && <slot></slot>}
        </div>
      </Host>
    );
  }
}
